mapper.select:
SELECT a.robot_id, a.robot_code, a.robot_name, a.robot_status, a.robot_type, a.robot_ip, b.dict_note AS robotTypeName, a.robot_position, c.dict_note AS robotPositionName, a.phote_path, d.region_name AS areaName, d.region_id AS areaId FROM t_robot_info a LEFT JOIN t_dict_business b ON a.robot_type = b.dict_code LEFT JOIN t_dict_business c ON a.robot_position = c.dict_code LEFT JOIN t_std_region d ON d.region_id = a.up_region_id where 1=1
and a.robot_type = #{robotType, jdbcType=VARCHAR}
AND a.drone_type IS NULL

SELECT a.robot_id, a.robot_code, a.robot_name, a.nest_code, a.nest_name, a.robot_status, a.drone_type, a.robot_ip, b.dict_note AS droneTypeName, a.drone_position, c.dict_note AS dronePositionName, a.phote_path, d.region_name AS areaName, d.region_id AS areaId FROM t_robot_info a LEFT JOIN t_dict_business b ON a.drone_type = b.dict_code LEFT JOIN t_dict_business c ON a.drone_position = c.dict_code LEFT JOIN t_std_region d ON d.region_id = a.up_region_id where 1=1
and a.drone_type = #{droneType, jdbcType=VARCHAR}
AND a.robot_type IS NULL

select robot_code
from t_robot_info
where robot_id = #{robotId,jdbcType=BIGINT}
